composition.definitions:
def unitPairs {d : ℕ} (S : Finset (EuclideanSpace ℝ (Fin d))) : ℕ :=
  ((S ×ˢ S).filter (fun pq : EuclideanSpace ℝ (Fin d) × EuclideanSpace ℝ (Fin d) =>
      dist pq.1 pq.2 = (1 : ℝ))).card

def unitDistMax (d n : ℕ) : ℕ :=
  sInf {m : ℕ | ∀ S : Finset (EuclideanSpace ℝ (Fin d)), S.card = n → unitPairs S ≤ m}

def HasMatchedAsymptotics (d : ℕ) : Prop :=
  ∃ (α c₁ c₂ : ℝ) (N : ℕ), 0 < c₁ ∧ c₁ ≤ c₂ ∧
    ∀ (n : ℕ), N ≤ n →
      c₁ * (n : ℝ)^α ≤ (unitDistMax d n : ℝ) ∧
      (unitDistMax d n : ℝ) ≤ c₂ * (n : ℝ)^α

